#pragma once

#include <ostream>

constexpr float LsEpsilon = 0.001f;

// operators generated by claude AI
template<typename T>
struct LsVec2 {
    T x, y;

    LsVec2& operator = (const LsVec2& other) = default;

    LsVec2& operator += (const LsVec2& o) { x += o.x; y += o.y; return *this; }
    LsVec2& operator -= (const LsVec2& o) { x -= o.x; y -= o.y; return *this; }
    LsVec2& operator *= (const LsVec2& o) { x *= o.x; y *= o.y; return *this; }
    LsVec2& operator /= (const LsVec2& o) { x /= o.x; y /= o.y; return *this; }

    LsVec2& operator += (T s) { x += s; y += s; return *this; }
    LsVec2& operator -= (T s) { x -= s; y -= s; return *this; }
    LsVec2& operator *= (T s) { x *= s; y *= s; return *this; }
    LsVec2& operator /= (T s) { x /= s; y /= s; return *this; }

    friend LsVec2 operator + (LsVec2 a, const LsVec2& b) { return a += b; }
    friend LsVec2 operator - (LsVec2 a, const LsVec2& b) { return a -= b; }
    friend LsVec2 operator * (LsVec2 a, const LsVec2& b) { return a *= b; }
    friend LsVec2 operator / (LsVec2 a, const LsVec2& b) { return a /= b; }

    friend LsVec2 operator + (LsVec2 a, T s) { return a += s; }
    friend LsVec2 operator - (LsVec2 a, T s) { return a -= s; }
    friend LsVec2 operator * (LsVec2 a, T s) { return a *= s; }
    friend LsVec2 operator / (LsVec2 a, T s) { return a /= s; }

    friend LsVec2 operator + (T s, LsVec2 a) { return a += s; }
    friend LsVec2 operator * (T s, LsVec2 a) { return a *= s; }

    friend LsVec2 operator - (T s, const LsVec2& a) { return { s - a.x, s - a.y }; }
    friend LsVec2 operator / (T s, const LsVec2& a) { return { s / a.x, s / a.y }; }

    friend bool operator == (const LsVec2& a, const LsVec2& b) { return a.x == b.x && a.y == b.y; }
    friend bool operator != (const LsVec2& a, const LsVec2& b) { return !(a == b); }
};

using LsVec2I = LsVec2<int>;
using LsVec2U = LsVec2<unsigned>;
using LsVec2F = LsVec2<float>;
using LsVec2D = LsVec2<double>;

struct LsColor {
    unsigned r = 255, g = 255, b = 255, a = 255;
};

constexpr LsColor LsBlank = {0, 0, 0, 0};
constexpr LsColor LsWhite = {255, 255, 255};

constexpr LsColor LsRed = {255, 0, 0};
constexpr LsColor LsBlue = {0, 0, 255};
constexpr LsColor LsGreen = {0, 255, 0};

constexpr LsColor LsYellow = {255, 255, 0};
constexpr LsColor LsPink = {255, 0, 255};
constexpr LsColor LsCyan = {0, 255, 255};

struct LsLine {
    LsVec2F start, end;

    [[nodiscard]] bool isPoint() const { return start == end; }

    LsLine(const LsVec2F& start, const LsVec2F& end) : start(start), end(end) {};
    explicit LsLine(const LsVec2F& point) : start(point), end(point) {};
    LsLine() = default;
};

template<typename T>
inline std::ostream& operator << (std::ostream& os, const LsVec2<T>& v) { return os << v.x << ", " << v.y; };

inline std::ostream& operator << (std::ostream& os, const LsColor& v) { return os << v.r << ", " << v.g << ", " << v.b << "; " << v.a;  }